-- Standalone PostgreSQL schema. IF NOT EXISTS preserves imported user data.
CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY,name varchar(255) NOT NULL,email varchar(255) UNIQUE NOT NULL,password varchar(255) NOT NULL,email_verified_at timestamp,created_at timestamp,updated_at timestamp);
CREATE TABLE IF NOT EXISTS access_tokens(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,digest char(64) UNIQUE NOT NULL,abilities jsonb NOT NULL DEFAULT '["*"]',expires_at timestamptz,last_used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS allowed_email_entries(id bigserial PRIMARY KEY,pattern varchar(255) UNIQUE NOT NULL,label varchar(255),is_active boolean NOT NULL DEFAULT true,created_at timestamp,updated_at timestamp);
CREATE TABLE IF NOT EXISTS app_settings(key varchar(255) PRIMARY KEY,value text,created_at timestamp,updated_at timestamp);
CREATE TABLE IF NOT EXISTS dictionary_entries(id bigserial PRIMARY KEY,word varchar(255) UNIQUE NOT NULL,phonetic varchar(120),audio_url text,source varchar(40) NOT NULL DEFAULT 'user_save',is_curated boolean NOT NULL DEFAULT false,save_count integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_meanings(id bigserial PRIMARY KEY,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id) ON DELETE CASCADE,part_of_speech varchar(40),definition text NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE INDEX IF NOT EXISTS dictionary_meanings_entry ON dictionary_meanings(dictionary_entry_id,position);
CREATE TABLE IF NOT EXISTS dictionary_examples(id bigserial PRIMARY KEY,dictionary_meaning_id bigint NOT NULL REFERENCES dictionary_meanings(id) ON DELETE CASCADE,example text NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_synonyms(id bigserial PRIMARY KEY,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id) ON DELETE CASCADE,dictionary_meaning_id bigint REFERENCES dictionary_meanings(id) ON DELETE CASCADE,term varchar(120) NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_antonyms(id bigserial PRIMARY KEY,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id) ON DELETE CASCADE,dictionary_meaning_id bigint REFERENCES dictionary_meanings(id) ON DELETE CASCADE,term varchar(120) NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS vocabularies(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id),times_quizzed integer NOT NULL DEFAULT 0,last_quizzed_at timestamp,last_correct_at timestamp,created_at timestamp NOT NULL,updated_at timestamp NOT NULL,UNIQUE(user_id,dictionary_entry_id));
CREATE TABLE IF NOT EXISTS quiz_attempts(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,vocabulary_id bigint NOT NULL REFERENCES vocabularies(id) ON DELETE CASCADE,correct boolean NOT NULL,question_type varchar(40) NOT NULL,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS game_records(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,game varchar(40) NOT NULL,best_correct integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL,UNIQUE(user_id,game));
CREATE TABLE IF NOT EXISTS media_items(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,title varchar(255) NOT NULL,url text NOT NULL,type varchar(20) NOT NULL,source_id varchar(255),audio_path varchar(255),audio_disk varchar(20) NOT NULL DEFAULT 'local',duration_seconds integer,language varchar(10) NOT NULL DEFAULT 'en',frequency varchar(20) NOT NULL DEFAULT 'weekly',difficulty varchar(20) NOT NULL DEFAULT 'intermediate',notes text,is_active boolean NOT NULL DEFAULT true,next_listen_at timestamp,analysis_status varchar(20) NOT NULL DEFAULT 'pending',analysis_error text,transcript text,transcript_segments jsonb,analysis_payload jsonb,analyzed_at timestamp,question_bank_status varchar(20) NOT NULL DEFAULT 'pending',question_bank_count integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS listen_logs(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,media_item_id bigint NOT NULL REFERENCES media_items(id) ON DELETE CASCADE,listened_at timestamp NOT NULL,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS listening_assessments(id bigserial PRIMARY KEY,media_item_id bigint NOT NULL REFERENCES media_items(id) ON DELETE CASCADE,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,type varchar(20) NOT NULL,title varchar(255) NOT NULL,description text,question_count integer NOT NULL DEFAULT 0,question_ids jsonb,time_limit_minutes integer,status varchar(20) NOT NULL DEFAULT 'ready',generated_at timestamp,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS listening_questions(id bigserial PRIMARY KEY,media_item_id bigint NOT NULL REFERENCES media_items(id) ON DELETE CASCADE,"order" integer NOT NULL DEFAULT 0,question_type varchar(40) NOT NULL,prompt text NOT NULL,options jsonb,correct_answer text NOT NULL,explanation text,audio_start_seconds integer,audio_end_seconds integer,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE INDEX IF NOT EXISTS listening_questions_media ON listening_questions(media_item_id);
CREATE TABLE IF NOT EXISTS listening_attempts(id bigserial PRIMARY KEY,listening_assessment_id bigint NOT NULL REFERENCES listening_assessments(id) ON DELETE CASCADE,media_item_id bigint REFERENCES media_items(id) ON DELETE CASCADE,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,type varchar(20),score integer NOT NULL DEFAULT 0,total integer NOT NULL DEFAULT 0,percentage numeric(5,2) NOT NULL DEFAULT 0,answers jsonb NOT NULL,started_at timestamp,completed_at timestamp,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
